using Xunit;

namespace Geometria.Tests;

public class TriangleTests
{
    [InlineData(3, 4, 5, true)]     // clásico
    [InlineData(10, 10, 10, true)]  // equilátero
    [InlineData(0, 0, 0, false)]    // no hay lados
    [InlineData(3, 4, -5, false)]   // lado negativo
    [InlineData(1, 1, 3, false)]    // dos lados no alcanzan al tercero
    [InlineData(7, 3, 2, false)]
    [InlineData(1, 1, 2, false)]    // degenerado: cae en línea recta
    [InlineData(5, 5, 9, true)]
    [Theory]
    public void EsValido(int a, int b, int c, bool expected) =>
        Assert.Equal(expected, Triangle.EsValido(a, b, c));
}

