using Xunit;

namespace Geometria.Tests;

public class TriangleTests
{
    [InlineData(3, 4, 5, true)]     // classic
    [InlineData(10, 10, 10, true)]  // equilateral
    [InlineData(0, 0, 0, false)]    // no sides at all
    [InlineData(3, 4, -5, false)]   // negative side
    [InlineData(1, 1, 3, false)]    // two sides don't reach the third
    [InlineData(7, 3, 2, false)]
    [InlineData(1, 1, 2, false)]    // degenerate: it collapses into a straight line
    [InlineData(5, 5, 9, true)]
    [Theory]
    public void EsValido(int a, int b, int c, bool expected) =>
        Assert.Equal(expected, Triangle.EsValido(a, b, c));
}

