namespace Geometria;

public static class Triangle
{
    public static bool EsValido(int a, int b, int c) =>
        a > 0 && b > 0 && c > 0;
}

namespace Geometria;

public static class Triangle
{
    public static bool EsValido(int a, int b, int c) =>
        a > 0 && b > 0 && c > 0
        && a + b > c && b + c > a && a + c > b;
}

